import { NextResponse } from 'next/server';

export async function POST(request: Request) {
    try {
        const data = await request.json();

        // Simulating CertControl validation
        if (!data.doc || data.doc.length < 11) {
            return NextResponse.json({
                error: "Ops! O documento informado parece inválido para este tipo de certificado."
            }, { status: 400 });
        }

        const protocol = "DELTA-" + Math.random().toString(36).substring(2, 9).toUpperCase();

        return NextResponse.json({
            success: true,
            protocol,
            message: "Pedido finalizado com sucesso! Link de pagamento gerado.",
            paymentLink: `https://checkout.delta.com.br/pay/${protocol}`
        }, { status: 201 });

    } catch (error) {
        return NextResponse.json({ error: "Erro interno na integração com CertControl." }, { status: 500 });
    }
}
